+#include <QStandardItemModel>
+#include <QTest>
+
+#include "abstracttasksmodel.h"
+#include "taskfilterproxymodel.h"
+
+using namespace Qt::StringLiterals;
+using namespace TaskManager;
+
+class TaskFilterProxyModelTest : public QObject
+{
+    Q_OBJECT
+
+private Q_SLOTS:
+    /**
+     * An activated launcher must come back when its window stops passing the
+     * filters because of a change to the window, e.g. when the window is moved
+     * to another virtual desktop.
+     *
+     * @see https://invent.kde.org/kde-linux/kde-linux/-/issues/833
+     */
+    void test_activatedLauncherReappears_data();
+    void test_activatedLauncherReappears();
+};
+
+void TaskFilterProxyModelTest::test_activatedLauncherReappears_data()
+{
+    QTest::addColumn<QString>("filter");
+    QTest::addColumn<int>("role");
+    QTest::addColumn<QVariant>("visibleValue");
+    QTest::addColumn<QVariant>("hiddenValue");
+
+    QTest::newRow("virtual desktop") << u"virtualDesktop"_s << int(AbstractTasksModel::VirtualDesktops) << QVariant(QVariantList{u"desktop1"_s})
+                                     << QVariant(QVariantList{u"desktop2"_s});
+    QTest::newRow("activity") << u"activity"_s << int(AbstractTasksModel::Activities) << QVariant(QStringList{u"activity1"_s})
+                              << QVariant(QStringList{u"activity2"_s});
+    QTest::newRow("skip taskbar") << u"skipTaskbar"_s << int(AbstractTasksModel::SkipTaskbar) << QVariant(false) << QVariant(true);
+}
+
+void TaskFilterProxyModelTest::test_activatedLauncherReappears()
+{
+    QFETCH(QString, filter);
+    QFETCH(int, role);
+    QFETCH(QVariant, visibleValue);
+    QFETCH(QVariant, hiddenValue);
+
+    QStandardItemModel sourceModel;
+
+    auto launcher = new QStandardItem;
+    launcher->setData(true, AbstractTasksModel::IsLauncher);
+    launcher->setData(u"org.kde.konsole"_s, AbstractTasksModel::AppId);
+    sourceModel.appendRow(launcher);
+
+    auto window = new QStandardItem;
+    window->setData(true, AbstractTasksModel::IsWindow);
+    window->setData(u"org.kde.konsole"_s, AbstractTasksModel::AppId);
+    window->setData(visibleValue, role);
+    sourceModel.appendRow(window);
+
+    TaskFilterProxyModel filterModel;
+    filterModel.setSourceModel(&sourceModel);
+    filterModel.setHideActivatedLaunchers(true);
+
+    if (filter == u"virtualDesktop") {
+        filterModel.setVirtualDesktop(u"desktop1"_s);
+        filterModel.setFilterByVirtualDesktop(true);
+    } else if (filter == u"activity") {
+        filterModel.setActivity(u"activity1"_s);
+        filterModel.setFilterByActivity(true);
+    } else {
+        filterModel.setFilterSkipTaskbar(true);
+    }
+
+    // The window passes the filters, so it hides its launcher.
+    QCOMPARE(filterModel.rowCount(), 1);
+    QVERIFY(filterModel.index(0, 0).data(AbstractTasksModel::IsWindow).toBool());
+
+    // The window no longer passes the filters, so the launcher has to come back.
+    window->setData(hiddenValue, role);
+    QCOMPARE(filterModel.rowCount(), 1);
+    QVERIFY(filterModel.index(0, 0).data(AbstractTasksModel::IsLauncher).toBool());
+
+    // And it is hidden again once the window passes the filters again.
+    window->setData(visibleValue, role);
+    QCOMPARE(filterModel.rowCount(), 1);
+    QVERIFY(filterModel.index(0, 0).data(AbstractTasksModel::IsWindow).toBool());
+}
+
+QTEST_GUILESS_MAIN(TaskFilterProxyModelTest)
+
+#include "taskfilterproxymodeltest.moc"
