 }

+bool TaskFilterProxyModel::Private::rolesAffectActivatedLaunchers(const QList<int> &roles) const
+{
+    // Activated launchers are hidden while a matching window or startup task passes the
+    // other filters, so a change that can affect whether that task passes has to re-filter.
+    if (roles.isEmpty()) {
+        return true;
+    }
+
+    const auto changed = [&roles](int role) {
+        return roles.contains(role);
+    };
+
+    if (changed(AbstractTasksModel::AppId) || changed(AbstractTasksModel::LauncherUrlWithoutIcon)) {
+        return true;
+    }
+    if (filterSkipTaskbar && changed(AbstractTasksModel::SkipTaskbar)) {
+        return true;
+    }
+    if (filterSkipPager && changed(AbstractTasksModel::SkipPager)) {
+        return true;
+    }
+    if ((filterByVirtualDesktop || filterByCurrentVirtualDesktop)
+        && (changed(AbstractTasksModel::VirtualDesktops) || changed(AbstractTasksModel::IsOnAllVirtualDesktops))) {
+        return true;
+    }
+    if ((filterByScreen || filterByCurrentVirtualDesktop) && changed(AbstractTasksModel::ScreenGeometry)) {
+        return true;
+    }
+    if (filterByRegion != RegionFilterMode::Mode::Disabled && changed(AbstractTasksModel::Geometry)) {
+        return true;
+    }
+    if (filterByActivity && changed(AbstractTasksModel::Activities)) {
+        return true;
+    }
+    // IsHidden follows the minimized state on Wayland, which only announces IsMinimized changes.
+    if ((filterMinimized || filterNotMinimized || filterHidden) && changed(AbstractTasksModel::IsMinimized)) {
+        return true;
+    }
+    if (filterHidden && changed(AbstractTasksModel::IsHidden)) {
+        return true;
+    }
+    if (filterNotMaximized && changed(AbstractTasksModel::IsMaximized)) {
+        return true;
+    }
+
+    return demandingAttentionSkipsFilters && changed(AbstractTasksModel::IsDemandingAttention);
+}
+
